Proceso SumaDiagonalSecundaria
    Dimension datos[3, 3] Como Entero;
    Definir fila Como Entero;
    Definir columna Como Entero;
    Definir total Como Entero;
    Para fila <- 0 Hasta 2 Con Paso 1 Hacer
        Para columna <- 0 Hasta 2 Con Paso 1 Hacer
            Leer datos[fila, columna];
        FinPara
    FinPara
    total <- datos[0, 2] + datos[1, 1] + datos[2, 0];
    Escribir total;
FinProceso
